-- PostgreSQL port of tables-mysql.sql (HC-250, proposed contribution).
--
-- Load into an empty database:
--     psql -d homecare -f tables-postgres.sql
-- or let `php bin/migrate.php` do it on first run (db_type: postgresql).
--
-- Changes from the MySQL original (keep them in sync when either moves):
--   * INT AUTO_INCREMENT PRIMARY KEY -> INTEGER GENERATED BY DEFAULT AS
--     IDENTITY PRIMARY KEY. "BY DEFAULT" (not ALWAYS) so explicit ids
--     still insert, as on MySQL. lastval() reports the generated id.
--   * DATETIME -> TIMESTAMP(0). Precision 0 keeps values at whole
--     seconds so they read back as 'YYYY-MM-DD HH:MM:SS', exactly the
--     shape MySQL returns and the PHP layer parses.
--   * BOOLEAN / TINYINT(1) -> SMALLINT. The app compares and binds these
--     as 1/0; a real PG boolean would reject `= 1` and read back as 't'/'f'.
--   * CHAR(1) 'Y'/'N' flags are kept as-is.
--   * ON UPDATE CURRENT_TIMESTAMP -> BEFORE UPDATE trigger
--     (hc_set_updated_at) on hc_patients and hc_medicines.
--   * Inline KEY / UNIQUE KEY -> CREATE INDEX / CREATE UNIQUE INDEX.
--   * ENGINE / CHARSET / COLLATE clauses dropped (database encoding
--     should be UTF8).
--   * Adds hc_api_rate_limit (migration 010), which tables-mysql.sql
--     does not carry, and the hc_migrations tracking table.
--
-- String comparison is case-sensitive on PostgreSQL (as on SQLite),
-- unlike MySQL's default *_ci collations. See docs/postgresql.md.

CREATE OR REPLACE FUNCTION hc_set_updated_at() RETURNS trigger AS $$
BEGIN
  NEW.updated_at := LOCALTIMESTAMP(0);
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TABLE hc_user (
  login VARCHAR(25) NOT NULL,
  passwd VARCHAR(255),
  lastname VARCHAR(25),
  firstname VARCHAR(25),
  is_admin CHAR(1) DEFAULT 'N',
  role VARCHAR(20) NOT NULL DEFAULT 'caregiver',
  email VARCHAR(75) NULL,
  enabled CHAR(1) DEFAULT 'Y',
  telephone VARCHAR(50) NULL,
  address VARCHAR(75) NULL,
  title VARCHAR(75) NULL,
  birthday INTEGER NULL,
  last_login INTEGER NULL,
  remember_token VARCHAR(64) NULL,
  remember_token_expires TIMESTAMP(0) NULL,
  failed_attempts INTEGER NOT NULL DEFAULT 0,
  locked_until TIMESTAMP(0) NULL,
  api_key_hash VARCHAR(255) NULL,
  totp_secret VARCHAR(64) NULL,
  totp_enabled CHAR(1) NOT NULL DEFAULT 'N',
  totp_recovery_codes TEXT NULL,
  email_notifications CHAR(1) NOT NULL DEFAULT 'N',
  notification_channels TEXT NOT NULL DEFAULT '[]',
  last_login_ip VARCHAR(45) NULL,
  digest_enabled CHAR(1) NOT NULL DEFAULT 'N',
  language VARCHAR(32) NULL,
  PRIMARY KEY (login)
);

CREATE TABLE hc_password_reset_tokens (
  token_hash CHAR(64) NOT NULL PRIMARY KEY,
  user_login VARCHAR(25) NOT NULL,
  created_at TIMESTAMP(0) NOT NULL,
  used_at TIMESTAMP(0) NULL,
  expires_at TIMESTAMP(0) NOT NULL
);
CREATE INDEX idx_prt_user_created ON hc_password_reset_tokens (user_login, created_at);

CREATE TABLE hc_remember_tokens (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_login VARCHAR(25) NOT NULL,
  token_hash CHAR(64) NOT NULL,
  expires_at TIMESTAMP(0) NOT NULL,
  device_name VARCHAR(128) NULL,
  last_ip VARCHAR(45) NULL,
  created_at TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  last_used_at TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX idx_remember_token_hash ON hc_remember_tokens (token_hash);
CREATE INDEX idx_remember_tokens_user ON hc_remember_tokens (user_login);

CREATE TABLE hc_patients (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  species VARCHAR(32) NULL,
  weight_kg DECIMAL(6,2) NULL,
  weight_as_of DATE NULL,
  created_at TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP,
  is_active SMALLINT NOT NULL DEFAULT 1
);
CREATE TRIGGER trg_hc_patients_updated_at BEFORE UPDATE ON hc_patients
  FOR EACH ROW EXECUTE FUNCTION hc_set_updated_at();

CREATE TABLE hc_drug_catalog (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  rxnorm_id INTEGER NULL,
  ndc VARCHAR(13) NULL,
  name VARCHAR(255) NOT NULL,
  strength VARCHAR(128) NULL,
  dosage_form VARCHAR(128) NULL,
  ingredient_names TEXT NULL,
  generic CHAR(1) NOT NULL DEFAULT 'N',
  created_at TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE UNIQUE INDEX idx_drug_catalog_rxnorm ON hc_drug_catalog (rxnorm_id);
CREATE INDEX idx_drug_catalog_name ON hc_drug_catalog (name);
CREATE INDEX idx_drug_catalog_ndc ON hc_drug_catalog (ndc);

CREATE TABLE hc_drug_interactions (
  ingredient_a VARCHAR(64) NOT NULL,
  ingredient_b VARCHAR(64) NOT NULL,
  severity VARCHAR(10) NOT NULL DEFAULT 'minor',
  description TEXT NULL,
  PRIMARY KEY (ingredient_a, ingredient_b)
);
CREATE INDEX idx_drug_interactions_b ON hc_drug_interactions (ingredient_b);

CREATE TABLE hc_attachments (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  owner_type VARCHAR(16) NOT NULL,
  owner_id INTEGER NOT NULL,
  filename VARCHAR(255) NOT NULL,
  mime_type VARCHAR(64) NOT NULL,
  size_bytes INTEGER NOT NULL,
  sha256 CHAR(64) NOT NULL,
  storage_path VARCHAR(255) NOT NULL,
  uploaded_by VARCHAR(25) NOT NULL,
  uploaded_at TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_attachments_owner ON hc_attachments (owner_type, owner_id);

CREATE TABLE hc_medicines (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  dosage VARCHAR(255) NOT NULL,
  drug_catalog_id INTEGER NULL,
  created_at TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT uq_medicines_name_dosage UNIQUE (name, dosage),
  CONSTRAINT fk_medicines_drug_catalog FOREIGN KEY (drug_catalog_id)
    REFERENCES hc_drug_catalog (id) ON DELETE SET NULL
);
CREATE TRIGGER trg_hc_medicines_updated_at BEFORE UPDATE ON hc_medicines
  FOR EACH ROW EXECUTE FUNCTION hc_set_updated_at();

CREATE TABLE hc_medicine_inventory (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  medicine_id INTEGER NOT NULL,
  quantity DECIMAL(10,2) NOT NULL,
  current_stock DECIMAL(10,2) NOT NULL,
  recorded_at TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP,
  note TEXT,
  FOREIGN KEY (medicine_id) REFERENCES hc_medicines (id) ON DELETE CASCADE
);

CREATE TABLE hc_medicine_schedules (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  patient_id INTEGER NOT NULL,
  medicine_id INTEGER NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE,
  frequency VARCHAR(255) NULL,
  unit_per_dose DECIMAL(10,2) NOT NULL DEFAULT 1.00,
  is_prn CHAR(1) NOT NULL DEFAULT 'N',
  dose_basis VARCHAR(10) NOT NULL DEFAULT 'fixed',
  cycle_on_days INTEGER NULL,
  cycle_off_days INTEGER NULL,
  wall_clock_times VARCHAR(128) NULL,
  created_at TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (patient_id) REFERENCES hc_patients (id) ON DELETE CASCADE,
  FOREIGN KEY (medicine_id) REFERENCES hc_medicines (id) ON DELETE CASCADE
);

CREATE TABLE hc_medicine_intake (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  schedule_id INTEGER NOT NULL,
  taken_time TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP,
  note TEXT,
  created_at TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (schedule_id) REFERENCES hc_medicine_schedules (id) ON DELETE CASCADE
);

CREATE TABLE hc_caregiver_notes (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  patient_id INTEGER NOT NULL,
  note TEXT NOT NULL,
  note_time TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP,
  created_at TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (patient_id) REFERENCES hc_patients (id) ON DELETE CASCADE
);

CREATE TABLE hc_config (
  setting VARCHAR(50) NOT NULL,
  value VARCHAR(128) NULL,
  PRIMARY KEY (setting)
);

CREATE TABLE hc_supply_alert_log (
  medicine_id INTEGER NOT NULL PRIMARY KEY,
  last_sent_at TIMESTAMP(0) NOT NULL
);

CREATE TABLE hc_late_dose_alert_log (
  schedule_id INTEGER NOT NULL PRIMARY KEY,
  last_due_at TIMESTAMP(0) NOT NULL,
  sent_at     TIMESTAMP(0) NOT NULL
);

CREATE TABLE hc_schedule_steps (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  schedule_id INTEGER NOT NULL,
  start_date DATE NOT NULL,
  unit_per_dose DECIMAL(10,3) NOT NULL,
  note VARCHAR(255) NULL,
  created_at TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (schedule_id) REFERENCES hc_medicine_schedules (id) ON DELETE CASCADE
);
CREATE INDEX idx_schedule_steps_sched ON hc_schedule_steps (schedule_id, start_date);

CREATE TABLE hc_schedule_pauses (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  schedule_id INTEGER NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NULL,
  reason VARCHAR(255) NULL,
  created_at TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (schedule_id) REFERENCES hc_medicine_schedules (id) ON DELETE CASCADE
);
CREATE INDEX idx_schedule_pauses_sched ON hc_schedule_pauses (schedule_id, start_date);

CREATE TABLE hc_audit_log (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_login VARCHAR(25) NULL,
  action VARCHAR(64) NOT NULL,
  entity_type VARCHAR(32) NULL,
  entity_id INTEGER NULL,
  details TEXT NULL,
  ip_address VARCHAR(64) NULL,
  created_at TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_hc_audit_log_user ON hc_audit_log (user_login, created_at);
CREATE INDEX idx_hc_audit_log_entity ON hc_audit_log (entity_type, entity_id);

CREATE TABLE hc_webhook_log (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  message_id VARCHAR(64) NOT NULL,
  url VARCHAR(512) NOT NULL,
  request_body TEXT NOT NULL,
  http_status INTEGER NULL,
  response_body TEXT NULL,
  error_message VARCHAR(512) NULL,
  attempt INTEGER NOT NULL DEFAULT 1,
  max_attempts INTEGER NOT NULL DEFAULT 4,
  elapsed_ms INTEGER NULL,
  success SMALLINT NOT NULL DEFAULT 0,
  created_at TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX idx_hc_webhook_log_message ON hc_webhook_log (message_id);
CREATE INDEX idx_hc_webhook_log_created ON hc_webhook_log (created_at DESC);
CREATE INDEX idx_hc_webhook_log_success ON hc_webhook_log (success, created_at DESC);

CREATE TABLE hc_weight_history (
  id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  patient_id INTEGER NOT NULL,
  weight_kg DECIMAL(6,2) NOT NULL,
  recorded_at DATE NOT NULL,
  note VARCHAR(255) NULL,
  created_at TIMESTAMP(0) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (patient_id) REFERENCES hc_patients (id) ON DELETE CASCADE
);
CREATE INDEX idx_hc_weight_history_patient ON hc_weight_history (patient_id, recorded_at DESC);

/* API rate limiting (HC-076, migration 010). */
CREATE TABLE hc_api_rate_limit (
  ip VARCHAR(45) NOT NULL,
  bucket VARCHAR(20) NOT NULL,
  window_start BIGINT NOT NULL,
  count INTEGER NOT NULL DEFAULT 0,
  PRIMARY KEY (ip, bucket, window_start)
);

/* Migration tracking, same shape as bin/migrate.php creates on MySQL.
   PostgreSQL migrations live in migrations/pgsql/. When one is added,
   fold its change into this file too and list its name below so a
   fresh install from this file does not re-apply it. */
CREATE TABLE hc_migrations (
  name VARCHAR(64) PRIMARY KEY,
  applied_at TIMESTAMP(0) DEFAULT CURRENT_TIMESTAMP
);
